const demoTracks=[{title:'Entre luces',artist:'Artista de muestra',duration:180},{title:'Pulso de la ciudad',artist:'NOODO · Session de muestra',duration:224},{title:'Después del encuentro',artist:'Colectivo de muestra',duration:196}];
function labButton(action,name,glyph,extra=''){return `<button class="icon-button ${extra}" data-player-action="${action}" aria-label="${name}">${icon(glyph)}</button>`;}
function labProgress(){return `<div class="lab-progress"><input type="range" min="0" max="180" value="0" data-player-seek aria-label="Posición de la pista en segundos"><div><output data-elapsed aria-live="off">0:00</output><span data-duration>3:00</span></div></div>`;}
function labTransport(){return `<div class="lab-transport">${labButton('shuffle','Activar reproducción aleatoria','shuffle')}${labButton('previous','Pista anterior','previous')}${labButton('play','Reproducir simulación silenciosa','play','button soft lab-play')}${labButton('next','Pista siguiente','next')}${labButton('repeat','Activar repetición','repeat')}</div>`;}
pages.player=()=>`${head('07B','Dale play<br>a la próxima conexión.','Biblioteca de componentes del reproductor: controles, carátula, progreso, volumen, cola y estados. Puedes probarlos aquí; la demostración es silenciosa.')}<div class="source-row" style="margin-bottom:28px"><a class="button primary" href="listen.html">Abrir diseño del reproductor web ↗</a><span class="small muted">Prototipo visual · vista completa · local</span></div><div class="player-lab" id="player-lab"><div class="player-showcase"><article class="lab-expanded glow-card"><div class="lab-cover"><img src="assets/artist-portrait-v02.png" alt="Retrato de artista ficticia generado con IA"><span class="tag glass-label">NOODO SELECTS · MUESTRA IA</span></div><div class="lab-body"><span class="eyebrow">REPRODUCTOR AMPLIADO</span><h2 data-track-title>Entre luces</h2><p data-track-artist>Artista de muestra</p>${labProgress()}${labTransport()}<div class="lab-volume">${labButton('mute','Silenciar simulación','volume')}<input type="range" min="0" max="100" value="70" data-player-volume aria-label="Volumen de muestra"><output data-volume-label aria-live="off">70%</output></div><p class="demo-label" data-player-status role="status">En pausa · simulación sin audio</p></div></article><div class="lab-side"><article class="panel glow-card"><span class="eyebrow">COLA DE REPRODUCCIÓN</span><h3>A continuación</h3><ol class="lab-queue">${demoTracks.map((t,i)=>`<li><button data-track="${i}" class="queue-track"><span class="queue-number">0${i+1}</span><span><strong>${t.title}</strong><small>${t.artist}</small></span><span>${Math.floor(t.duration/60)}:${String(t.duration%60).padStart(2,'0')}</span></button></li>`).join('')}</ol><p class="small muted">Selecciona una pista para comprobar la sincronización de los componentes.</p></article><article class="panel glass-card"><span class="eyebrow">ANATOMÍA DEL REPRODUCTOR</span><ul class="divider-list"><li><strong>Identidad</strong><span>Carátula, título y artista.</span></li><li><strong>Transporte</strong><span>Anterior, play/pausa, siguiente, mezcla y repetición.</span></li><li><strong>Control</strong><span>Progreso, tiempo, volumen y silencio.</span></li></ul></article></div></div>${label('MiniPlayer','Variante compacta · aislada del producto')}<div class="mini-player glass-card"><img src="assets/artist-portrait-v02.png" alt="" class="mini-cover"><div class="mini-info"><strong data-track-title>Entre luces</strong><small data-track-artist>Artista de muestra</small></div>${labButton('previous','Pista anterior','previous')}${labButton('play','Reproducir simulación silenciosa','play','button soft')}${labButton('next','Pista siguiente','next')}<div class="mini-progress">${labProgress()}</div>${labButton('expand','Ver reproductor ampliado','expand')}</div><p class="source">Las dos variantes comparten el estado de esta muestra. No se fija una barra sobre el catálogo.</p>${label('Estados del componente','Prueba interactiva')}<div class="panel"><label class="field">Estado del reproductor<select id="lab-state"><option value="ready">Disponible</option><option value="loading">Cargando</option><option value="error">Error de conexión</option><option value="unavailable">Contenido no disponible</option><option value="empty">Cola vacía</option></select></label><div class="notice info" id="lab-state-message" role="status">Listo para probar. No hay audio conectado.</div><button class="button" id="lab-retry" hidden style="margin-top:16px">Reintentar muestra</button></div></div><div class="callout"><strong>Contrato de integración:</strong> los componentes ya están disponibles para revisión visual. El proveedor musical aún debe confirmar qué controles permite su API. No hay reproducción real ni autoplay.</div>${label('Reglas de interacción')}<ul class="divider-list"><li><strong>Teclado</strong><span>Tab para controles; flechas para los rangos. Nombres accesibles cambian con play/pausa y silencio.</span></li><li><strong>Continuidad</strong><span>Mini y ampliado conservan pista, progreso, mezcla, repetición y volumen durante esta demostración.</span></li><li><strong>Estados</strong><span>Carga, error y contenido no disponible detienen el avance y deshabilitan el transporte. El error ofrece reintento.</span></li><li><strong>Fin de pista</strong><span>Avanza por la cola; al final se pausa. Repetición recorre la cola; mezcla elige otra pista.</span></li></ul>`;
function bindPlayerLab(){
 const root=$('#player-lab');if(!root)return;
 let track=0,position=0,playing=false,volume=70,lastVolume=70,shuffle=false,repeat=false,mode='ready';
 const all=s=>$$(s,root),fmt=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
 function update(){const t=demoTracks[track],blocked=mode!=='ready';
  all('[data-track-title]').forEach(e=>e.textContent=mode==='empty'?'Sin pistas en la cola':t.title);
  all('[data-track-artist]').forEach(e=>e.textContent=mode==='empty'?'Añade música para empezar':t.artist);
  all('[data-elapsed]').forEach(e=>e.textContent=fmt(position));all('[data-duration]').forEach(e=>e.textContent=fmt(t.duration));
  all('[data-player-seek]').forEach(e=>{e.max=t.duration;e.value=position;e.disabled=blocked;e.setAttribute('aria-valuetext',`${fmt(position)} de ${fmt(t.duration)}`);});
  all('[data-player-volume]').forEach(e=>{e.value=volume;e.disabled=blocked;e.setAttribute('aria-valuetext',volume+' por ciento');});all('[data-volume-label]').forEach(e=>e.textContent=volume+'%');
  all('[data-player-action]').forEach(b=>{let a=b.dataset.playerAction;b.disabled=blocked&&a!=='expand';if(a==='play'){b.innerHTML=icon(playing?'pause':'play');b.setAttribute('aria-label',playing?'Pausar simulación silenciosa':'Reproducir simulación silenciosa');b.setAttribute('aria-pressed',String(playing));}if(a==='mute'){b.innerHTML=icon(volume===0?'mute':'volume');b.setAttribute('aria-label',volume===0?'Restaurar volumen de muestra':'Silenciar simulación');b.setAttribute('aria-pressed',String(volume===0));}if(a==='repeat'||a==='shuffle'){const active=a==='repeat'?repeat:shuffle;b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',(active?'Desactivar ':'Activar ')+(a==='repeat'?'repetición':'reproducción aleatoria'));}});
  all('[data-track]').forEach(b=>{const active=Number(b.dataset.track)===track&&mode!=='empty';b.setAttribute('aria-current',String(active));b.disabled=blocked;b.parentElement.hidden=mode==='empty';});
  $('[data-player-status]',root).textContent=(blocked?{loading:'Cargando muestra…',error:'Error de conexión',unavailable:'Contenido no disponible',empty:'Cola vacía'}[mode]:playing?'Reproduciendo':'En pausa')+' · simulación sin audio';
 }
 function next(manual=false){if(shuffle)track=(track+1+Math.floor(Math.random()*(demoTracks.length-1)))%demoTracks.length;else if(track<demoTracks.length-1)track++;else if(repeat||manual)track=0;else {playing=false;position=demoTracks[track].duration;return;}position=0;}
 all('[data-player-action]').forEach(b=>b.addEventListener('click',()=>{switch(b.dataset.playerAction){case 'play':if(position>=demoTracks[track].duration)position=0;playing=!playing;break;case 'previous':track=(track+demoTracks.length-1)%demoTracks.length;position=0;break;case 'next':next(true);break;case 'shuffle':shuffle=!shuffle;break;case 'repeat':repeat=!repeat;break;case 'mute':if(volume){lastVolume=volume;volume=0;}else volume=lastVolume||70;break;case 'expand':const target=$('.lab-expanded',root);target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'center'});$('[data-player-action=play]',target).focus({preventScroll:true});break;}update();}));
 all('[data-player-seek]').forEach(e=>e.addEventListener('input',()=>{position=Number(e.value);if(position>=demoTracks[track].duration)playing=false;update();}));
 all('[data-player-volume]').forEach(e=>e.addEventListener('input',()=>{volume=Number(e.value);if(volume)lastVolume=volume;update();}));
 all('[data-track]').forEach(b=>b.addEventListener('click',()=>{track=Number(b.dataset.track);position=0;update();}));
 function setMode(value){mode=value;playing=false;if(mode==='empty')position=0;const messages={ready:'Listo para probar. No hay audio conectado.',loading:'Cargando… Se reserva el espacio y se deshabilitan los controles.',error:'No pudimos conectar. Reintenta para recuperar el estado de muestra.',unavailable:'Esta grabación ya no está disponible. Controles deshabilitados.',empty:'No hay pistas en la cola. Selecciona Disponible para restaurar la muestra.'};$('#lab-state-message').textContent=messages[mode];$('#lab-state-message').className='notice '+(mode==='error'?'error':'info');$('#lab-retry').hidden=mode!=='error';update();}
 $('#lab-state').addEventListener('change',e=>setMode(e.target.value));$('#lab-retry').addEventListener('click',()=>{$('#lab-state').value='ready';setMode('ready');});
 pageTimers.push(setInterval(()=>{if(playing&&mode==='ready'){position++;if(position>=demoTracks[track].duration)next();update();}},1000));update();
}

